import net.sf.*
import net.sf.json.*
import net.sf.json.groovy.*

import com.eviware.soapui.support.XmlHolder
import net.sf.*
import net.sf.json.*
import net.sf.json.groovy.*
import Utiliti.StatusReportCred;



//Obtener el codigo de estado
def statusCode = messageExchange.responseStatusCode

//Invocamos el nombre del paso de prueba
String nameSteps = context.currentStep.name.toString();

//Llamar al transaction_id en caso de 200

//name TestStep para msj, 409, 400
def msj = context.expand('${' + nameSteps + '#Response#$.message}')

switch (statusCode){

	case 200:
	  //sleep(20000)  
	  def transaction_id = context.expand('${' + nameSteps + '#Response#$.transaction_id}')
	  def get = new URL("https://pruebas.sypago.net:8086/api/v1/transaction/" + transaction_id).openConnection();

	  get.setRequestProperty("Authorization", context.expand('${#Project#Authorization}'))

  	  def response = get.getInputStream().getText()
  	  def jsonSlurper = new JsonSlurper().parseText(response)

	  def TxSts = jsonSlurper.status
       assert TxSts == "PEND" || "ACCP"
       log.info TxSts

	  def Rsn = jsonSlurper.rejected_code
	  //assert Rsn == ""
	 break;

	 case 400:
	 case 401:
	 case 409:
  	  def token = context.expand('${#Project#Authorization}');
       log.info msj;
	  assert statusCode == statusCode;
	  break;

	  default:
	   log.info("Status code: " + statusCode)
	  break;

}

